  const int Capacity=33;
  sealed class Entry{public Renderer body,fade;public string id;public Material[] original,own;public float progress,hold;public uint lo,hi;public ModelLod lod;public int lodIndex;public int screenFrame=-1;public float minX,minY,maxX,maxY,minZ;public float appliedProgress=-1;public uint appliedLo,appliedHi;}
  sealed class ModelLod {public LODGroup group;public LOD[] levels;public int selected;}
  readonly List<ModelLod> modelLods=new List<ModelLod>();
  readonly List<Entry> entries=new List<Entry>();MaterialPropertyBlock block;readonly Vector4[] circles=new Vector4[Capacity];readonly List<Vector4> combat=new List<Vector4>();readonly List<Vector3> points=new List<Vector3>();readonly List<bool> projectile=new List<bool>();
  Camera viewer;Transform sceneWorld;Func<Vector3> hero;Func<Bounds> heroBounds;Action<List<Vector4>> collect;A2RSightQuery query;RenderTexture nearest;readonly Vector3[] heroSamples=new Vector3[5];
  public int HeroPartialSurfaces {get;private set;}
