  [Serializable] public sealed class NativeCoverage {public int candidates,wrapped,unsupported;public List<NativeMaterialCheck> materials=new List<NativeMaterialCheck>();}
  public bool Applied{get;private set;}public bool MasksEnabled{get;private set;}=true;
  public int NearestDrawCalls{get;private set;}public int FadedRenderers{get;private set;}public int VisibleTargets{get;private set;}public int PeakDroppedTargets{get;private set;}public int EdgeFadedRenderers{get{return 0;}}public int SightSurfaces{get;private set;}public int HeroSightSurfaces{get;private set;}public int ProjectileSightSurfaces{get;private set;}public int ForegroundFarTargets{get;private set;}
  public readonly List<string> HitNames=new List<string>();
  public A2RForegroundComposition.Receipt CompositionReport{get{return new A2RForegroundComposition.Receipt();}}
  public void Initialize(Transform world,Camera camera,Func<Vector3> player){block=new MaterialPropertyBlock();sceneWorld=world;viewer=camera;hero=player;query=new A2RSightQuery();RenderPipelineManager.beginCameraRendering+=NearestPass;
   foreach(var root in world.gameObject.scene.GetRootGameObjects())foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true))if(NativeCandidate(r))Wrap(r);
   SetLook(false);
  }
  static bool NativeCandidate(Renderer r){if(r==null||PathOf(r.transform).Contains("A2R")||r.bounds.size.y<.35f)return false;var f=r.GetComponent<MeshFilter>();if(f==null||f.sharedMesh==null)return false;string path=PathOf(r.transform);bool objectName=path.IndexOf("tree",StringComparison.OrdinalIgnoreCase)>=0||path.IndexOf("branch",StringComparison.OrdinalIgnoreCase)>=0||path.IndexOf("rock",StringComparison.OrdinalIgnoreCase)>=0||path.IndexOf("bridge",StringComparison.OrdinalIgnoreCase)>=0||path.Contains("거목")||path.Contains("목교")||path.Contains("바위");if(path.Contains("A2 전체 필드 지면")||path.Contains("A2 흙에 이어진 스캔 뿌리"))return false;foreach(var m in r.sharedMaterials){if(m==null||m.shader==null)continue;string n=m.shader.name;if(n.Contains("Water")||n.Contains("River")||n.Contains("Fog")||n.Contains("DistanceHaze")||n.Contains("Atmosphere")||n.Contains("Contact")||n.Contains("GroundSkill")||(!objectName&&(n.Contains("Ground")||n.Contains("RootSurface"))))return false;}return true;}
  void Wrap(Renderer r){var f=r.GetComponent<MeshFilter>();if(f==null||f.sharedMesh==null)return;var old=r.sharedMaterials;var a=new Material[old.Length];var b=new Material[old.Length];for(int i=0;i<old.Length;i++){if(old[i]==null)continue;a[i]=new Material(old[i]){name=old[i].name+" A2R runtime opaque",shader=Resources.Load<Shader>("A2R/LitOpaque")};b[i]=new Material(old[i]){name=old[i].name+" A2R runtime fade",shader=Resources.Load<Shader>("A2R/LitFade")};foreach(var m in new[]{a[i],b[i]}){string key=old[i].HasProperty("_BaseMap")?"_BaseMap":old[i].HasProperty("_MainTex")?"_MainTex":null;if(key!=null){m.SetTexture("_BaseMap",old[i].GetTexture(key));m.SetTextureScale("_BaseMap",old[i].GetTextureScale(key));m.SetTextureOffset("_BaseMap",old[i].GetTextureOffset(key));}if(!old[i].HasProperty("_BaseColor")&&old[i].HasProperty("_Color"))m.SetColor("_BaseColor",old[i].GetColor("_Color"));}a[i].renderQueue=2460;b[i].renderQueue=3000;}
   var go=new GameObject("A2R sight circle portion");go.transform.SetParent(r.transform,false);go.AddComponent<MeshFilter>().sharedMesh=f.sharedMesh;var fade=go.AddComponent<MeshRenderer>();fade.sharedMaterials=b;fade.shadowCastingMode=ShadowCastingMode.Off;fade.enabled=false;entries.Add(new Entry{body=r,fade=fade,original=old,own=a,id=PathOf(r.transform)});r.sharedMaterials=a;
  }
  public void Register(Renderer body,Renderer faded,bool eligible,bool rearClip){entries.Add(new Entry{body=body,fade=faded,id=PathOf(body.transform)});}
  public void RegisterModel(Transform model,string label){int start=entries.Count;var source=new List<MeshRenderer>(model.GetComponentsInChildren<MeshRenderer>(true));foreach(var r in source){Wrap(r);entries[entries.Count-1].id=label+" / "+PathOf(r.transform);}foreach(var group in model.GetComponentsInChildren<LODGroup>(true)){var state=new ModelLod{group=group,levels=group.GetLODs(),selected=0};var combined=new LOD[state.levels.Length];for(int i=0;i<combined.Length;i++){var renderers=new List<Renderer>(state.levels[i].renderers);for(int j=start;j<entries.Count;j++){var e=entries[j];if(!renderers.Contains(e.body))continue;e.lod=state;e.lodIndex=i;renderers.Add(e.fade);}combined[i]=new LOD(state.levels[i].screenRelativeTransitionHeight,renderers.ToArray());}group.SetLODs(combined);group.ForceLOD(0);modelLods.Add(state);}}
  void SelectModelLods(){foreach(var state in modelLods){var g=state.group;if(g==null||!g.gameObject.activeInHierarchy)continue;var scale=g.transform.lossyScale;float size=g.size*Mathf.Max(Mathf.Abs(scale.x),Mathf.Max(Mathf.Abs(scale.y),Mathf.Abs(scale.z)));float distance=Vector3.Distance(viewer.transform.position,g.transform.TransformPoint(g.localReferencePoint));float relative=QualitySettings.lodBias*size/(viewer.orthographic?2*viewer.orthographicSize:2*Mathf.Max(.01f,distance)*Mathf.Tan(viewer.fieldOfView*Mathf.Deg2Rad*.5f));int selected=state.levels.Length-1;for(int i=0;i<state.levels.Length;i++)if(relative>=state.levels[i].screenRelativeTransitionHeight){selected=i;break;}selected=Mathf.Clamp(Mathf.Max(selected,QualitySettings.maximumLODLevel),0,state.levels.Length-1);if(selected!=state.selected){state.selected=selected;g.ForceLOD(selected);}}}
  public void SetHeroBounds(Func<Bounds> bounds){heroBounds=bounds;}
  public void ProtectLandmark(Renderer card){}
  public void SetCombatSource(Action<List<Vector4>> source){collect=source;}
  public void SetLook(bool on){Applied=on;foreach(var e in entries){if(e.body==null)continue;if(e.original!=null)e.body.sharedMaterials=on?e.own:e.original;e.progress=0;e.lo=e.hi=0;e.hold=0;Apply(e);e.fade.enabled=on;}Shader.SetGlobalFloat("_A2RHoleCount",0);}
  public void SetMasksEnabled(bool on){MasksEnabled=on;foreach(var e in entries){e.progress=0;e.lo=e.hi=0;e.hold=0;Apply(e);}Shader.SetGlobalFloat("_A2RHoleCount",0);}
  void Apply(Entry e){if(e.body==null)return;if(e.progress==e.appliedProgress&&e.lo==e.appliedLo&&e.hi==e.appliedHi)return;e.appliedProgress=e.progress;e.appliedLo=e.lo;e.appliedHi=e.hi;e.body.GetPropertyBlock(block);block.SetFloat("_A2RFade",e.progress);block.SetFloat("_A2RHoleA",e.lo&0xFFFFu);block.SetFloat("_A2RHoleB",e.lo>>16);block.SetFloat("_A2RHoleC",e.hi);e.body.SetPropertyBlock(block);if(e.fade!=null)e.fade.SetPropertyBlock(block);}
  public NativeCoverage CheckNativeCoverage(){var report=new NativeCoverage();foreach(var root in sceneWorld.gameObject.scene.GetRootGameObjects())foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true)){if(!NativeCandidate(r))continue;report.candidates++;var e=entries.Find(x=>x.body==r&&x.original!=null);var active=r.sharedMaterials;var check=new NativeMaterialCheck{id=PathOf(r.transform),activeShaders=new string[active.Length],holeSupported=e!=null,sourcePropertiesKept=e!=null};check.originalShaders=new string[e!=null?e.original.Length:0];for(int i=0;i<active.Length;i++){var m=active[i];check.activeShaders[i]=m!=null?m.shader.name:"null";if(m!=null&&m.FindPass("A2RNearest")<0)check.holeSupported=false;if(e==null||i>=e.original.Length||m==null||e.original[i]==null)continue;var old=e.original[i];check.originalShaders[i]=old.shader.name;foreach(string key in new[]{"_BaseMap","_BumpMap","_MetallicGlossMap","_OcclusionMap"})if(old.HasProperty(key)&&m.HasProperty(key)&&old.GetTexture(key)!=m.GetTexture(key))check.sourcePropertiesKept=false;if(old.HasProperty("_BaseColor")&&m.HasProperty("_BaseColor")&&old.GetColor("_BaseColor")!=m.GetColor("_BaseColor"))check.sourcePropertiesKept=false;}if(check.holeSupported&&check.sourcePropertiesKept)report.wrapped++;else report.unsupported++;report.materials.Add(check);}return report;}
  public bool IsSightBlocked(Vector3 point,out string name){return IsSightBlockedFrom(viewer.transform.position,point,out name);}
  public bool IsSightBlockedFrom(Vector3 eye,Vector3 point,out string name,string filter=null){foreach(var e in entries){if(e.body==null)continue;string id=e.id;if(filter!=null&&id.IndexOf(filter,StringComparison.OrdinalIgnoreCase)<0)continue;Vector3 hit;if(query.Hit(e.body,eye,point,out hit)){name=e.id;return true;}}name="";return false;}
  public List<Bounds> LandmarkBounds(string contains){var result=new List<Bounds>();foreach(var e in entries)if(e.body!=null&&(e.body.name.IndexOf(contains,StringComparison.OrdinalIgnoreCase)>=0||e.body.transform.parent!=null&&e.body.transform.parent.name.IndexOf(contains,StringComparison.OrdinalIgnoreCase)>=0))result.Add(e.body.bounds);return result;}
  public void LateUpdate(){if(!Applied||viewer==null)return;SelectModelLods();FadedRenderers=SightSurfaces=HeroSightSurfaces=HeroPartialSurfaces=ProjectileSightSurfaces=ForegroundFarTargets=0;HitNames.Clear();points.Clear();projectile.Clear();if(!MasksEnabled){Shader.SetGlobalFloat("_A2RHoleCount",0);return;}
   var bounds=heroBounds!=null?heroBounds():new Bounds(hero()+Vector3.up*.8f,new Vector3(.8f,1.6f,.2f));float height=ScreenHeight(bounds);Add(bounds.center,height*1.3f);combat.Clear();if(collect!=null)collect(combat);var at=hero();combat.Sort((a,b)=>(new Vector3(a.x,a.y,a.z)-at).sqrMagnitude.CompareTo((new Vector3(b.x,b.y,b.z)-at).sqrMagnitude));int used=0;foreach(var t in combat){var p=new Vector3(t.x,t.y,t.z);float distance=new Vector2(p.x-at.x,p.z-at.z).magnitude;bool far=distance>14;if(far&&t.w<0)continue;if(far){string id;if(!IsSightBlocked(p,out id))continue;ForegroundFarTargets++;}if(used>=32){PeakDroppedTargets++;continue;}var v=viewer.WorldToScreenPoint(p);if(v.z<=0||v.x<0||v.x>viewer.pixelWidth||v.y<0||v.y>viewer.pixelHeight)continue;float h=ScreenHeight(new Bounds(p,Vector3.one*Mathf.Abs(t.w)));if(Add(p,Mathf.Max(24,h*1.2f),t.w<0))used++;}
    heroSamples[0]=bounds.center;heroSamples[1]=bounds.center+viewer.transform.up*bounds.size.y*.35f;heroSamples[2]=bounds.center-viewer.transform.up*bounds.size.y*.25f;heroSamples[3]=bounds.center+viewer.transform.right*Mathf.Min(bounds.extents.x*.55f,.45f);heroSamples[4]=bounds.center-viewer.transform.right*Mathf.Min(bounds.extents.x*.55f,.45f);
    VisibleTargets=points.Count;Shader.SetGlobalMatrix("_A2RViewportVP",viewer.projectionMatrix*viewer.worldToCameraMatrix);Shader.SetGlobalMatrix("_A2RNearestView",viewer.worldToCameraMatrix);Shader.SetGlobalVector("_A2RHoleScreen",new Vector4(viewer.pixelWidth,viewer.pixelHeight,0,0));Shader.SetGlobalVectorArray("_A2RHoles",circles);Shader.SetGlobalFloat("_A2RHoleCount",points.Count);
    foreach(var e in entries){if(e.body==null||e.fade==null)continue;if(e.lod!=null&&e.lodIndex!=e.lod.selected){e.fade.enabled=false;e.progress=0;e.lo=e.hi=0;Apply(e);continue;}if(e.own!=null){var current=e.body.sharedMaterials;bool replaced=current.Length!=e.own.Length;for(int i=0;!replaced&&i<current.Length;i++)replaced=current[i]!=e.own[i];if(replaced)e.body.sharedMaterials=e.own;}e.fade.enabled=Applied&&e.body.enabled;uint lo=0,hi=0;if(e.body.enabled&&e.body.gameObject.activeInHierarchy){for(int i=0;i<points.Count;i++){bool blocked=CoversCircle(e,i);if(blocked&&i==0)HeroPartialSurfaces++;if(!blocked)continue;if(i<32)lo|=1u<<i;else hi|=1u<<(i-32);if(i==0)HeroSightSurfaces++;else if(projectile[i])ProjectileSightSurfaces++;} }
    bool hitAny=(lo|hi)!=0;if(hitAny){e.lo=lo;e.hi=hi;e.hold=Time.unscaledTime+.12f;SightSurfaces++;HitNames.Add(e.id);}bool active=hitAny||Time.unscaledTime<e.hold;e.progress=Mathf.MoveTowards(e.progress,active?1:0,Time.unscaledDeltaTime/.2f);if(e.progress>0)FadedRenderers++;else e.lo=e.hi=0;Apply(e);
   }
  }
  // 시야선 광선이 가지 옆을 스쳐 지나가도, 화면에서 대상 원과 겹치고 대상보다 카메라 쪽에 있는 물체는 구멍 대상이다. 픽셀 단위 앞뒤는 셰이더 깊이 비교가 정한다.
  bool CoversCircle(Entry e,int i){if(e.screenFrame!=Time.frameCount){e.screenFrame=Time.frameCount;var b=e.body.bounds;e.minX=e.minY=e.minZ=float.PositiveInfinity;e.maxX=e.maxY=float.NegativeInfinity;for(int k=0;k<8;k++){var p=viewer.WorldToViewportPoint(b.center+Vector3.Scale(b.extents,new Vector3((k&1)==0?-1:1,(k&2)==0?-1:1,(k&4)==0?-1:1)));if(p.z<=0)continue;e.minX=Mathf.Min(e.minX,p.x);e.maxX=Mathf.Max(e.maxX,p.x);e.minY=Mathf.Min(e.minY,p.y);e.maxY=Mathf.Max(e.maxY,p.y);e.minZ=Mathf.Min(e.minZ,p.z);}}var c=circles[i];if(float.IsPositiveInfinity(e.minZ)||e.minZ>=c.w)return false;float rx=c.z/Mathf.Max(1,viewer.pixelWidth),ry=c.z/Mathf.Max(1,viewer.pixelHeight);return c.x+rx>e.minX&&c.x-rx<e.maxX&&c.y+ry>e.minY&&c.y-ry<e.maxY;}
  static string PathOf(Transform t){string n=t.name;for(int i=0;i<5&&t.parent!=null;i++){t=t.parent;n=t.name+"/"+n;}return n;}
  bool Add(Vector3 world,float radius,bool isProjectile=false){if(points.Count>=Capacity)return false;var v=viewer.WorldToViewportPoint(world);if(v.z<=0)return false;circles[points.Count]=new Vector4(v.x,v.y,radius,v.z);points.Add(world);projectile.Add(isProjectile);return true;}
  float ScreenHeight(Bounds b){float lo=float.PositiveInfinity,hi=float.NegativeInfinity;for(int i=0;i<8;i++){var p=viewer.WorldToScreenPoint(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));if(p.z>0){lo=Mathf.Min(lo,p.y);hi=Mathf.Max(hi,p.y);}}return float.IsPositiveInfinity(lo)?48:Mathf.Max(4,hi-lo);}
  void NearestPass(ScriptableRenderContext context,Camera camera){if(camera!=viewer)return;Shader.SetGlobalFloat("_A2RNearestReady",0);NearestDrawCalls=0;if(!Applied||!MasksEnabled||FadedRenderers==0)return;int width=camera.pixelWidth,height=camera.pixelHeight;if(nearest==null||nearest.width!=width||nearest.height!=height){if(nearest!=null){nearest.Release();Destroy(nearest);}nearest=new RenderTexture(width,height,0,SystemInfo.SupportsBlendingOnRenderTextureFormat(RenderTextureFormat.RFloat)?RenderTextureFormat.RFloat:RenderTextureFormat.ARGBHalf){filterMode=FilterMode.Point};nearest.Create();}
   var cmd=CommandBufferPool.Get("A2R sight surface once");cmd.SetGlobalMatrix("_A2RNearestVP",GL.GetGPUProjectionMatrix(camera.projectionMatrix,true)*camera.worldToCameraMatrix);cmd.SetGlobalMatrix("_A2RNearestView",camera.worldToCameraMatrix);cmd.SetGlobalFloat("_A2RDepthTolerance",nearest.format==RenderTextureFormat.RFloat?.003f:.025f);cmd.SetRenderTarget(nearest);cmd.SetViewport(new Rect(0,0,width,height));cmd.ClearRenderTarget(false,true,new Color(camera.farClipPlane,camera.farClipPlane,camera.farClipPlane,camera.farClipPlane));foreach(var e in entries){if(e.progress<=0||e.body==null||!e.body.enabled||!e.body.gameObject.activeInHierarchy||(e.lod!=null&&e.lodIndex!=e.lod.selected))continue;var filter=e.body.GetComponent<MeshFilter>();if(filter==null||filter.sharedMesh==null)continue;var materials=e.body.sharedMaterials;e.body.GetPropertyBlock(block);for(int i=0;i<materials.Length;i++){var m=materials[i];if(m==null)continue;int pass=m.FindPass("A2RNearest");if(pass>=0){cmd.DrawMesh(filter.sharedMesh,e.body.localToWorldMatrix,m,i,pass,block);NearestDrawCalls++;}}}cmd.SetGlobalTexture("_A2RNearestDepth",nearest);cmd.SetGlobalFloat("_A2RNearestReady",1);context.ExecuteCommandBuffer(cmd);CommandBufferPool.Release(cmd);
  }
  public int NearestCoveredPixels(){if(nearest==null||NearestDrawCalls==0)return 0;var old=RenderTexture.active;var sample=new Texture2D(nearest.width,nearest.height,TextureFormat.RGBAFloat,false,true);try{RenderTexture.active=nearest;sample.ReadPixels(new Rect(0,0,nearest.width,nearest.height),0,0);sample.Apply();var data=sample.GetRawTextureData<float>();int count=0;for(int i=0;i<data.Length;i+=4)if(data[i]>0&&data[i]<viewer.farClipPlane-.1f)count++;return count;}finally{RenderTexture.active=old;Destroy(sample);}}
  void OnDestroy(){RenderPipelineManager.beginCameraRendering-=NearestPass;if(query!=null)query.Dispose();if(nearest!=null){nearest.Release();Destroy(nearest);}Shader.SetGlobalFloat("_A2RHoleCount",0);Shader.SetGlobalFloat("_A2RNearestReady",0);}
 }
